def slope(w):
    return 2 * (w - 3)

print([slope(w) for w in [0, 1, 2, 3]])   # [-6, -4, -2, 0]: rises by 2 per unit
print(2)                                   # the curvature, L'' = 2

def loss(w):
    return (w - 3) ** 2

w = 0.0
slope, curve = 2 * (w - 3), 2   # L'(0) = -6 and L''(0) = 2
for d in [0.6, 3.0]:
    print(d, round(loss(w) + slope * d + 0.5 * curve * d ** 2, 2))   # 0.6 5.76 / 3.0 0.0
